INSERT INTO feature VALUES('capabilities','effects','Capabilities with authority, grade, region and footprint',NULL,'implemented','uncommon','mainstream languages','A capability names the effects it authorises and the scope it lives in, and forging, amplifying, dropping or escaping one is refused by name. An operation the host answers stands beside an open end, and one a scope answers captures what the scope opened. The two halves of a fork share a capability''s interface only to read through it.','core-checker core-sequent','corpus/model/control/capability-region.gandr corpus/model/control/capability-attenuate.gandr corpus/pathological/control/capability-forge.gandr corpus/model/tasks/authority.gandr corpus/model/cancellation/resumed.gandr','corpus/model/control/capability-region.gandr',NULL);
